1363	  if (_navigationDirection.lengthSq() < 0.04) {
1364	    controls.forward = false;
1365	    controls.backward = false;
1366	    controls.left = false;
1367	    controls.right = false;
1368	    return;
1369	  }
1370	  const intent = surfaceSteeringIntent(_navigationDirection, up, getPlayerLook().forward);
1371	  controls.forward = intent.forward;
1372	  controls.backward = intent.backward;
1373	  controls.right = intent.right;
1374	  controls.left = intent.left;
1375	}
