1396	  // wait — so the shot stays on the thing that just happened instead of
1397	  // whipping away from it on the same frame.
1398	  if (screeningSettling()) {
1399	    _target.copy(target);
1400	    walkTargetLive = true;
1401	    controls.forward = false;
1402	    controls.backward = false;
1403	    controls.left = false;
1404	    controls.right = false;
1405	    controls.jump = false;
