    // Tangential component only: the planner owns the surface height it cleared,
    // and the body walks the remainder under ordinary steering.
    const up = getPlayerUp();
    _exactGoalOffset.copy(goal).sub(waypoint);
    _exactGoalOffset.addScaledVector(up, -_exactGoalOffset.dot(up));
    _navigationWaypoint.add(_exactGoalOffset);
  }
  return {
    waypoint: _navigationWaypoint,
    action: navigationAction,
    route: active.route,
    preserveForward: false
  };
}

