function clearCrossFaceContinuation(): void {
  crossFaceContinuationMinUntil = -1;
  crossFaceContinuationMaxUntil = -1;
  crossFaceContinuationProbeAt = -1;
  crossFaceContinuationFace = null;
  crossFaceContinuationExpectsDry = false;
