1153	/**
1154	 * May the EXACT requested goal own the last leg, instead of the snapped cell?
1155	 *
1156	 * Every A* waypoint is `voxelCoordToWorld(cell.support)` — a cell CENTRE — and
1157	 * the terminal one is never consumed, so it stays the steering target forever.
1158	 * `steerFreeToward` then releases all four controls inside tangent radius
1159	 * `NAVIGATION_STEER_DEAD_ZONE`, while `walkToward` only arrives on the distance
1160	 * to the goal the caller actually asked for. With `VOXEL_SCALE` 2 a goal may sit
1161	 * up to one unit off its own cell centre, so the closest the body can come while
1162	 * steering is still live is `offset - 0.2`. Chapter 13 aims 0.6 THROUGH each
1163	 * route corner (`CG_RAIL_CORNER_OVERSHOOT`, which is what keeps arc credit at or
1164	 * under real displacement) and stops at 0.35: 0.6 - 0.2 = 0.4 > 0.35, so the
1165	 * arrival predicate was not merely unlucky, it was unsatisfiable. The body
1166	 * parked, every control false — which is also why the stuck watchdog never
1167	 * armed, since it only counts stillness while the pilot is PUSHING.
1168	 *
1169	 * The repair is deliberately the smallest one that exists: when the planner
1170	 * resolved the goal's OWN cell, the exact goal is already inside a footprint A*
1171	 * certified for dryness, clearance, slope and edge margin. Steering to it is
1172	 * ordinary walking within a region the navigator has already cleared — no radius
1173	 * is widened, no dead zone is weakened, no cell is skipped, and a goal the
1174	 * planner had to substitute for safety (water, hazard, no clearance) keeps the
1175	 * safe cell exactly as before.
1176	 */
1177	export function terminalExactGoalHandoff(input: {
1178	  route: Pick<
1179	    AgentSurfaceRoute,
1180	    'mode' | 'reason' | 'waypoints' | 'requestedGoalWasWet' | 'waterCrossing'
1181	  >;
1182	  cursor: number;
1183	  goal: THREE.Vector3;
1184	  action: NavigationAction;
1185	  face: CubeFace;
1186	  goalFace: CubeFace;
1187	  crossFaceLegActive: boolean;
1188	}): TerminalGoalHandoff {
1189	  const { route, cursor, goal } = input;
1190	  const refuse = (refusal: TerminalGoalHandoffRefusal): TerminalGoalHandoff =>
1191	    ({ handoff: false, refusal });
1192	  const terminal = route.waypoints[route.waypoints.length - 1];
1193	  if (!terminal || cursor !== route.waypoints.length - 1) {
1194	    return refuse('not-terminal-waypoint');
1195	  }
1196	  // A cross-face trip is owned by the edge machinery above; the goal is not on
1197	  // the face this body is standing on and its cell index is not comparable.
1198	  if (input.crossFaceLegActive || input.face !== input.goalFace) {
1199	    return refuse('cross-face-goal');
1200	  }
1201	  // Jetpack legs and water crossings keep the planner's cleared waypoint.
1202	  if (input.action === 'jetpack' || route.waterCrossing !== null) {
1203	    return refuse('water-leg');
1204	  }
1205	  // A goal the planner REPLACED is not inside the region it resolved. Keeping
1206	  // the safe approach cell is the whole protection for wet, hazardous and
1207	  // unclearable goals, and it stays.
1208	  if (
1209	    route.requestedGoalWasWet
1210	    || (route.reason !== 'dry-surface-path' && route.reason !== 'already-at-resolved-goal')
1211	  ) {
1212	    return refuse('goal-substituted-for-safety');
1213	  }
1214	  // The decisive test, and the one that keeps this inside the navigator: the
1215	  // exact goal must quantize to the very cell A* certified and terminated on.
1216	  if (
1217	    navigationCellIndex(goal.x) !== navigationCellIndex(terminal.x)
1218	    || navigationCellIndex(goal.y) !== navigationCellIndex(terminal.y)
1219	    || navigationCellIndex(goal.z) !== navigationCellIndex(terminal.z)
1220	  ) {
1221	    return refuse('goal-outside-terminal-cell');
1222	  }
1223	  return { handoff: true, refusal: null };
1224	}
