export function commonGroundSnapshot(worldId = currentWorldId()): CommonGroundSnapshot {
  const actorId = getLocalActorId();
  const live = readCommonGroundLive(worldId);
  // A live snapshot that has actually done or restored something is the truth,
  // full stop: a payload staged behind it must never overwrite newer real work.
  if (live && live.actorId === actorId && !isPristineCommonGround(live)) return live;
  // A PRISTINE one is only a placeholder. It gets minted by whichever director
  // tick asks first, and at boot that can precede `restoreCommonGroundForWorld`
  // for the world being left — which is exactly how an earned survey came back
  // as `phase: idle`. If this world's saved bytes have since been staged, they
  // win over the placeholder; the staged payload still goes through the same
  // actor/world validator, and a restored snapshot still enters steady and
  // silent, so nothing already earned is replayed into fresh AV history.
  if (live && live.actorId === actorId && !hasStagedCommonGroundPayload(worldId)) return live;
  const staged = takeCommonGroundWorldPayload(worldId);
  const hydrated = staged == null ? null : migrateCommonGround(staged, actorId, worldId);
  // A rejected payload (another actor, another world, malformed) must not
  // discard the placeholder identity either; it simply initializes local state.
  const snapshot = hydrated
    ?? (live && live.actorId === actorId ? live : createCommonGroundSnapshot(actorId, worldId));
  putCommonGroundLive(snapshot);

