#!/usr/bin/env python3
"""Behavioural counterfactual for the Continue loss (CG-IMPL-011 / 008).

The byte-swap alone only shows the repaired API is absent on old bytes. This
probe is written against ONLY pre-existing exports, so the SAME file runs on
both byte sets and the difference it reports is behaviour, not API surface.

Task-private, byte-exact, try/finally, hash-asserted. The temporary spec lives
inside main/src only for the duration of this script and its removal is proven.
Never touches Git.
"""
import hashlib
import json
import shutil
import subprocess
import tempfile
from pathlib import Path

REPO = Path("/home/thomasphillip/Projects/vox")
RUN = REPO / ".codex/production-runs/2026-09-05-after-the-hearth"
BEFORE = RUN / "iterations/implemented-world-repair/source"

TARGETS = [
    "main/src/story/commonGroundState.ts",
    "main/src/story/commonGroundDirector.ts",
    "main/src/game/systems/persistence.ts",
]
SPEC_REL = "main/src/story/__continue-counterfactual.test.ts"

SPEC = r"""
import { describe, expect, it } from 'vitest';
import * as THREE from 'three';
import { setPlayerUp, setPlayerWorldPosition } from '../state/playerFrame.ts';
import { resetProgression } from '../game/systems/progressionSystem.ts';
import {
  resetSystemFlightForInterstellarArrival
} from '../state/spaceFlight.ts';
import { STORY_COORDINATE, STORY_PRIMARY_WORLD_ID, STORY_SEED } from './world/storyWorldIdentity.ts';
import { CG_POSES, CG_ROUTE_SHORT, clearAllCommonGroundWorlds } from './commonGroundState.ts';
import {
  commitCommonGroundDemonstrationOffer,
  commitCommonGroundSurveyStart,
  commonGroundSnapshot,
  enterCommonGroundBeat,
  registerCommonGroundWorld,
  resetCommonGroundRuntime,
  tickCommonGround
} from './commonGroundDirector.ts';
import { resetCommonGroundActor, seedCommonGroundActorPose } from './commonGroundActor.ts';
import { saveWorld } from '../game/systems/persistence.ts';

class MemStorage {
  private map = new Map<string, string>();
  get length() { return this.map.size; }
  key(i: number) { return [...this.map.keys()][i] ?? null; }
  getItem(k: string) { return this.map.get(k) ?? null; }
  setItem(k: string, v: string) { this.map.set(k, String(v)); }
  removeItem(k: string) { this.map.delete(k); }
  clear() { this.map.clear(); }
}

const flatGround = {
  supportY: () => 51.05,
  isSupported: () => true,
  revision: 'counterfactual'
} as unknown as Parameters<typeof registerCommonGroundWorld>[0]['footing'];

function standAt(p: { x: number; y: number; z: number }): void {
  setPlayerWorldPosition(new THREE.Vector3(p.x, p.y, p.z));
}

describe('COUNTERFACTUAL: does an autosave destroy the world it left?', () => {
  it('reports what the stored survey phase becomes', () => {
    (globalThis as unknown as { localStorage: MemStorage }).localStorage = new MemStorage();
    setPlayerUp(new THREE.Vector3(0, 1, 0));
    resetProgression();
    clearAllCommonGroundWorlds();
    resetCommonGroundRuntime({ clearWorlds: true });
    resetCommonGroundActor();

    const world = { worldId: STORY_PRIMARY_WORLD_ID, seed: STORY_SEED };
    resetSystemFlightForInterstellarArrival({
      system: STORY_COORDINATE,
      activePlanetId: STORY_PRIMARY_WORLD_ID,
      locationMode: 'surface',
      pose: { position: [0, 0, 0], velocity: [0, 0, 0], quaternion: [0, 0, 0, 1] }
    });
    let unbind = registerCommonGroundWorld({
      worldId: STORY_PRIMARY_WORLD_ID, footing: flatGround, extraSolids: []
    });

    // Earn a real partial drawing.
    enterCommonGroundBeat('ch13-survey');
    seedCommonGroundActorPose(CG_POSES.W);
    standAt(CG_POSES.W);
    for (let f = 0; f < 20; f += 1) tickCommonGround(0.016);
    expect(commitCommonGroundDemonstrationOffer()).toBe(true);
    standAt(CG_POSES.S);
    expect(commitCommonGroundSurveyStart()).toBe(true);
    for (const point of CG_ROUTE_SHORT.slice(1, 4)) {
      standAt(point);
      tickCommonGround(0.016);
    }
    tickCommonGround(0.016);
    expect(commonGroundSnapshot().survey.phase).toBe('drawing');
    saveWorld(world);

    // Cold Continue boot. Nothing restored. A read mints a placeholder for the
    // world being left, then story entry moves to the sibling and the
    // world-change autosave writes Origin.
    resetCommonGroundRuntime({ clearWorlds: true });
    resetCommonGroundActor();
    unbind?.();
    unbind = registerCommonGroundWorld({
      worldId: STORY_PRIMARY_WORLD_ID, footing: flatGround, extraSolids: []
    });
    commonGroundSnapshot(STORY_PRIMARY_WORLD_ID);
    resetSystemFlightForInterstellarArrival({
      system: STORY_COORDINATE,
      activePlanetId: `${STORY_PRIMARY_WORLD_ID}:p1`,
      locationMode: 'surface',
      pose: { position: [0, 0, 0], velocity: [0, 0, 0], quaternion: [0, 0, 0, 1] }
    });
    enterCommonGroundBeat('ch13-return');
    tickCommonGround(0.016);
    saveWorld(world);

    const raw = (globalThis as unknown as { localStorage: MemStorage })
      .localStorage.getItem(`pvx.v1.world.${STORY_PRIMARY_WORLD_ID}`)!;
    const stored = JSON.parse(raw) as {
      commonGround?: { survey?: { phase?: string; working?: unknown } };
    };
    const phase = stored.commonGround?.survey?.phase ?? 'absent';
    const samples = (stored.commonGround?.survey?.working as { samples?: unknown[] } | null)
      ?.samples?.length ?? 0;
    console.log(`COUNTERFACTUAL_RESULT phase=${phase} samples=${samples} bytes=${raw.length}`);
    unbind?.();
  });
});
"""


def sha(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def run_spec(label: str) -> dict:
    result = subprocess.run(
        ["npx", "vitest", "run", "src/story/__continue-counterfactual.test.ts"],
        cwd=str(REPO / "main"), capture_output=True, text=True, timeout=900,
    )
    blob = result.stdout + result.stderr
    line = next(
        (l.strip() for l in blob.splitlines() if "COUNTERFACTUAL_RESULT" in l), "MISSING"
    )
    print(f"[{label}] exit={result.returncode} :: {line}")
    (RUN / f"tmp/continue-counterfactual-{label}.txt").write_text(blob[-8000:])
    return {"label": label, "exitCode": result.returncode, "observed": line}


def main() -> int:
    spec = REPO / SPEC_REL
    if spec.exists():
        raise SystemExit("counterfactual spec path already occupied; refusing")
    backup = Path(tempfile.mkdtemp(prefix="continue-cf-", dir=str(RUN / "tmp")))
    repaired, before_sha = {}, {}
    findings = []
    try:
        for rel in TARGETS:
            repaired[rel] = sha(REPO / rel)
            before_sha[rel] = sha(BEFORE / rel)
            dest = backup / rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(REPO / rel, dest)
            assert sha(dest) == repaired[rel]

        spec.write_text(SPEC)
        findings.append(run_spec("repaired"))

        for rel in TARGETS:
            shutil.copy2(BEFORE / rel, REPO / rel)
            assert sha(REPO / rel) == before_sha[rel]
        findings.append(run_spec("pre-repair"))
    finally:
        ok = True
        for rel in TARGETS:
            shutil.copy2(backup / rel, REPO / rel)
            if sha(REPO / rel) != repaired[rel]:
                ok = False
                print(f"RESTORE FAILED {rel}")
        spec.unlink(missing_ok=True)
        spec_removed = not spec.exists()
        for rel in TARGETS:
            assert sha(BEFORE / rel) == before_sha[rel], f"before-source mutated: {rel}"
        print("restoreVerified:", ok, "specRemoved:", spec_removed)
        (RUN / "tmp/continue-counterfactual-result.json").write_text(json.dumps({
            "findings": findings,
            "restoreVerified": ok,
            "temporarySpecRemoved": spec_removed,
